#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
[[ -f .next/standalone/server.js ]] || {
  echo "Run npm run build with standalone output first." >&2
  exit 1
}
# This directory is generated by this script; never point it at source data.
rm -rf deployment
mkdir -p deployment/.next
cp -R .next/standalone/. deployment/
cp -R .next/static deployment/.next/
if [[ -d public ]]; then cp -R public deployment/; fi
cp lambda-entry.js deployment/index.js
# Inspect this directory for credentials and unintended files before deploying.
echo "Packaged application in ./deployment"
